function dropDigit(number: string, digit: string): string {
  let best = "";
  for (let i = 0; i < number.length; i++) {
    if (number[i] !== digit) continue;
    const cand = number.slice(0, i) + number.slice(i + 1);
    if (cand > best) best = cand;
  }
  return best;
}

