class Solution:
    def dropDigit(self, number: str, digit: str) -> str:
        last = -1
        for i, c in enumerate(number):
            if c != digit:
                continue
            last = i
            if i + 1 < len(number) and number[i + 1] > digit:
                return number[:i] + number[i + 1:]
        return number[:last] + number[last + 1:]

